&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les &#233;coles de magie&lt;a class=&quot;headeranchor&quot; id=&quot;Les_&#233;coles_de_magie_0&quot; href=&quot;#Les_&#233;coles_de_magie_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;coles-De-Magie.html&quot; title=&quot;Les &#233;coles de magie du magicien&quot;&gt;pr&#233;sentation&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Abjuration-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Abjuration&quot;&gt;Abjuration&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Air-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de l&amp;#39;Air&quot;&gt;Air&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bois-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du Bois&quot;&gt;Bois&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Divination-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de Divination&quot;&gt;Divination&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Eau-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de l&amp;#39;Eau&quot;&gt;Eau&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enchantement-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Enchantement&quot;&gt;Enchantement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vocation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;&#201;vocation&quot;&gt;&#201;vocation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feu-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du Feu&quot;&gt;Feu&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Illusion-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Illusion&quot;&gt;Illusion&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invocation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Invocation&quot;&gt;Invocation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tal-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du M&#233;tal&quot;&gt;M&#233;tal&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;ant-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du N&#233;ant&quot;&gt;N&#233;ant&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;cromancie-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de N&#233;cromancie&quot;&gt;N&#233;cromancie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terre-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de la Terre&quot;&gt;Terre&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transmutation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de Transmutation&quot;&gt;Transmutation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Universelle-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole Universelle&quot;&gt;&#201;cole universelle&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Plus d&#39;information sur les sorts de cette &#233;cole &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#NECROMANCIE&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;ici&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Les n&#233;cromanciens sont des magiciens terrifiants et souvent craints qui commandent aux morts-vivants et utilisent les sombres pouvoirs de la non-vie contre leurs ennemis.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Emprise sur les morts-vivants (Sur).&lt;/b&gt; Le n&#233;cromancien re&#231;oit &lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le des morts-vivants&quot;&gt;Contr&#244;le des morts-vivants&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Renvoi-Des-Morts-Vivants.html&quot; title=&quot;Renvoi des morts-vivants&quot;&gt;Renvoi des morts-vivants&lt;/a&gt; comme &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#DONSUPPLEMENTAIRE&quot; title=&quot;Le magicien&quot;&gt;don suppl&#233;mentaire&lt;/a&gt;. Chaque jour, il peut canaliser de l’&#233;nergie un nombre de fois &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;, mais seulement pour utiliser le don choisi. Il peut acqu&#233;rir d’autres dons permettant d’am&#233;liorer ce pouvoir (comme &lt;a class=&quot;pagelink&quot; href=&quot;Canalisation-Suppl&#233;mentaire.html&quot; title=&quot;Canalisation suppl&#233;mentaire&quot;&gt;Canalisation suppl&#233;mentaire&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Canalisation.html&quot; title=&quot;Science de la canalisation&quot;&gt;Science de la canalisation&lt;/a&gt;) mais pas ceux qui le modifient (comme &lt;a class=&quot;pagelink&quot; href=&quot;Canalisation-Align&#233;e.html&quot; title=&quot;Canalisation align&#233;e&quot;&gt;Canalisation align&#233;e&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Canalisation-&#201;l&#233;mentaire.html&quot; title=&quot;Canalisation &#233;l&#233;mentaire&quot;&gt;Canalisation &#233;l&#233;mentaire&lt;/a&gt;). Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du jet de sauvegarde contre ces dons est &#233;gal &#224; 10 + la moiti&#233; du niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; du n&#233;cromancien + le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; du n&#233;cromancien. Lorsque le n&#233;cromancien atteint le niveau 20, les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt; ne peuvent plus ajouter leur &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Canalisation-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la canalisation (Ext)&quot;&gt;r&#233;sistance &#224; la canalisation&lt;/a&gt; &#224; leur &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; contre ce pouvoir.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Toucher du tombeau (Mag).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le n&#233;cromancien peut porter une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquesdecontact.html&quot; title=&quot;attaque de contact au corps &#224; corps&quot;&gt;attaque de contact au corps &#224; corps&lt;/a&gt; visant &#224; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secouer&lt;/a&gt; une cr&#233;ature vivante pendant un nombre de rounds &#233;gal &#224; la moiti&#233; de son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; (1 round au minimum). S’il touche &#224; nouveau une cr&#233;ature d&#233;j&#224; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;e&lt;/a&gt; par ce pouvoir, elle devient &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Effray&#233;.html&quot; title=&quot;Effray&#233;&quot;&gt;effray&#233;e&lt;/a&gt; pour 1 round si elle poss&#232;de un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; inf&#233;rieur au niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; du n&#233;cromancien. Chaque jour, le n&#233;cromancien peut utiliser ce pouvoir un nombre de fois &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Perception de la vie (Sur).&lt;/b&gt; Au niveau 8, le n&#233;cromancien peut acqu&#233;rir le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Aveugle-(Capacit&#233;).html&quot; title=&quot;vision aveugle&quot;&gt;vision aveugle&lt;/a&gt; avec une port&#233;e de 3 m (2 cases) chaque jour pendant un nombre total de rounds &#233;gal &#224; son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. Ce pouvoir lui permet seulement de d&#233;tecter et de distinguer les cr&#233;atures vivantes et les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt;. Les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Artificielle.html&quot; title=&quot;Cr&#233;ature artificielle&quot;&gt;cr&#233;atures artificielles&lt;/a&gt; et les autres cr&#233;atures qui ne sont ni vivantes ni &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;mortes-vivantes&lt;/a&gt; ne sont pas visibles. La port&#233;e de ce pouvoir augmente de 3 m (2 cases) au niveau 12, ainsi que tous les quatre niveaux au-del&#224; du niveau 12. Ces rounds ne doivent pas forc&#233;ment &#234;tre cons&#233;cutifs.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Champs d&#39;&#233;tude magiques&lt;a class=&quot;headeranchor&quot; id=&quot;Champs_d&#233;tude_magiques_0&quot; href=&quot;#Champs_d&#233;tude_magiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magiciens&lt;/a&gt; qui se sp&#233;cialisent dans une &#233;cole de magie peuvent choisir de restreindre davantage encore leur domaine d’&#233;tude. Les &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magiciens&lt;/a&gt; qui choisissent un champ d’&#233;tude magique conservent les sorts en bonus de leur &#233;cole de sp&#233;cialisation et doivent toujours s&#233;lectionner deux &#233;coles oppos&#233;es mais certains de leurs pouvoirs d’&#233;cole de magie sont modifi&#233;s ou remplac&#233;s. Ils doivent accepter toutes les modifications impos&#233;es par leur champ d’&#233;tude. Une fois un champ d’&#233;tude choisi, cette d&#233;cision ne peut plus &#234;tre modifi&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;table class=&quot;page espace-col deuxcol&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Morts-vivants&lt;a class=&quot;headeranchor&quot; id=&quot;Morts-vivants_1&quot; href=&quot;#Morts-vivants_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;b&gt;Pouvoirs remplac&#233;s.&lt;/b&gt; Le pouvoir d’&#233;cole suivant remplace &lt;i&gt;Toucher du tombeau&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Renforcement d’un mort-vivant (Mag).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut toucher une cr&#233;ature morte-vivante et lui transmettre de l’&#233;nergie n&#233;gative. Elle gagne un bonus impie de +1 aux jets d’attaque et jets de sauvegarde ainsi que 1 point de vie temporaire par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; et un bonus de +2 &#224; sa &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Canalisation-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la canalisation (Ext)&quot;&gt;r&#233;sistance &#224; la canalisation&lt;/a&gt;. Le bonus aux jets d’attaque et jets de sauvegarde augmente de +1 par tranche de cinq &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveaux&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. Ces bonus persistent pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal &#224; la moiti&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; (minimum 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;). Les bonus et les points de vie temporaires sont imm&#233;diatement dissip&#233;s si la cr&#233;ature p&#233;n&#232;tre dans la zone d’un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cons&#233;cration.html&quot; title=&quot;Cons&#233;cration&quot;&gt;cons&#233;cration&lt;/a&gt;&lt;/i&gt;. Le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut utiliser cette capacit&#233; un nombre de fois par jour &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;
&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Vie&lt;a class=&quot;headeranchor&quot; id=&quot;Vie_2&quot; href=&quot;#Vie_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;b&gt;Pouvoirs remplac&#233;s.&lt;/b&gt; Les pouvoirs d’&#233;cole suivants remplacent &lt;i&gt;Emprise sur les morts-vivants&lt;/i&gt; et &lt;i&gt;Toucher du tombeau&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Magie de vie (Sur).&lt;/b&gt; Chaque fois que le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; lance un sort visant plusieurs cibles, affectant les cr&#233;atures au sein d’une zone ou n&#233;cessitant un jet d’attaque, il peut gu&#233;rir les cr&#233;atures affect&#233;es par le sort d’un total de 1 point de vie par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; du sort. Ces points de vie peuvent &#234;tre distribu&#233;s entre les cibles du sort au gr&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. S’il d&#233;signe un mort-vivant comme &#171; b&#233;n&#233;ficiaire &#187; d’une partie de ces soins, celui-ci subit 1 point de d&#233;g&#226;t par point de vie assign&#233;. Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 11, le total de points de vie gu&#233;ris passe &#224; 2 points par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; du sort. La gu&#233;rison se produit au moment o&#249; le sort est lanc&#233; et ne produit aucun effet sur les cr&#233;atures qui p&#233;n&#232;trent dans la zone une fois que le sort est d&#233;j&#224; en place. Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 20, le total de points de vie gu&#233;ris passe &#224; 3 points par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; du sort.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Partage d’essence (Mag).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut choisir de partager son &#233;nergie vitale avec une cr&#233;ature vivante qu’il touche. Il subit 1d6 points de d&#233;g&#226;ts non l&#233;taux + 1 point par tranche de deux &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveaux&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. Cette quantit&#233; ne peut toutefois jamais &#233;galer ni d&#233;passer le nombre de points de vie qu’il lui reste (les points de d&#233;g&#226;t exc&#233;dentaires sont annul&#233;s). Le b&#233;n&#233;ficiaire du sort gagne un nombre de points de vie temporaires &#233;gal &#224; la quantit&#233; de d&#233;g&#226;ts que le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; a effectivement subis. Ces points de vie temporaires persistent pendant 1 heure. Le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; ne peut pas utiliser cette capacit&#233; pour s’octroyer des points de vie temporaires &#224; lui-m&#234;me. Il peut l’utiliser un nombre de fois par jour &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;. Cette capacit&#233; n’a aucun effet si le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; est &lt;a class=&quot;pagelink&quot; href=&quot;Immunit&#233;-(Capacit&#233;).html&quot; title=&quot;Immunit&#233; (Ext ou Sur)&quot;&gt;immunis&#233;&lt;/a&gt; aux d&#233;g&#226;ts non l&#233;taux.
&lt;/div&gt;
&lt;/table&gt;
